const S = {};
for (const i of $('Load settings').all()) { if (i.json.key) S[i.json.key] = String(i.json.value == null ? '' : i.json.value).trim(); }
const owner = (S.owner_email || 'stellanrowbotham@gmail.com').toLowerCase();
const leads = $('Load leads').all().map(i => i.json).filter(r => r && r.id);
const done = new Set($('Load processed replies').all().map(i => String(i.json.detail || '')).filter(Boolean));
const byThread = {}; for (const r of leads) { if (r.gmail_thread_id) byThread[r.gmail_thread_id] = r; }
const out = [];
for (const it of $('New Gmail message').all()) {
  const m = it.json || {};
  const id = String(m.id || ''); const thread = String(m.threadId || '');
  if (!id || done.has(id)) continue;
  const fromText = String((m.from && (m.from.text || m.from.value?.[0]?.address)) || m.From || '').toLowerCase();
  if (fromText.includes(owner)) continue;
  let text = String(m.text || m.snippet || '');
  text = text.split(/\n(?:On .{5,200} wrote:|-----Original Message-----|From: .*stellanrowbotham)/i)[0].slice(0, 4000);
  let lead = byThread[thread];
  const bounceHint = /mailer-daemon|postmaster|mail delivery subsystem/i.test(fromText) || /delivery status notification|undeliverable|address not found/i.test(String(m.subject || ''));
  if (!lead && bounceHint) { const raw = String(m.text || '').toLowerCase(); lead = leads.find(r => r.public_email && r.gmail_message_id && raw.includes(String(r.public_email).toLowerCase())); }
  if (!lead) continue;
  out.push({ json: { message_id: id, thread_id: thread, from: fromText.slice(0, 200), subject: String(m.subject || '').slice(0, 200), text: text, bounce_hint: bounceHint, lead_id: lead.id, lead_status: String(lead.status || '').toUpperCase(), lead_email: lead.public_email || '', business_name: lead.business_name || '', campaign_id: lead.campaign_id || '', owner: owner, booking_link: S.booking_link || '' } });
}
return out;

const c = $('Loop replies').first().json;
let k = $json.output || null;
const CATS = ['POSITIVE_INTEREST','MEETING_REQUEST','PRICING_QUESTION','SERVICE_QUESTION','NOT_NOW','REFERRAL','NOT_INTERESTED','UNSUBSCRIBE','OUT_OF_OFFICE','BOUNCED','UNCLEAR'];
const aiFailed = !k || !CATS.includes(k.category);
if (aiFailed) k = { category: 'UNCLEAR', summary: 'AI classification unavailable; please read this reply yourself.', main_question: '', interest_level: '', requested_next_step: '', proposed_meeting_time: '', needs_human: true };
let cat = k.category;
if (c.bounce_hint && cat !== 'BOUNCED') cat = 'BOUNCED';
if (/\b(unsubscribe|remove me|stop emailing|do not contact|don't contact|stop contacting|take me off)\b/i.test(c.text) && cat !== 'BOUNCED') cat = 'UNSUBSCRIBE';
const MAP = { POSITIVE_INTEREST: 'POSITIVE_INTEREST', MEETING_REQUEST: 'POSITIVE_INTEREST', PRICING_QUESTION: 'REPLIED', SERVICE_QUESTION: 'REPLIED', NOT_NOW: 'REPLIED', REFERRAL: 'REPLIED', NOT_INTERESTED: 'NOT_INTERESTED', UNSUBSCRIBE: 'SUPPRESSED', OUT_OF_OFFICE: '', BOUNCED: 'BOUNCED', UNCLEAR: 'REPLIED' };
const RANK = { NEW: 0, NEEDS_REVIEW: 1, APPROVED: 2, SENDING: 3, SENT: 4, REPLIED: 5, NOT_INTERESTED: 6, POSITIVE_INTEREST: 7, MEETING_BOOKED: 8, CUSTOMER: 9 };
let next = MAP[cat];
const cur = c.lead_status;
if (cur === 'SUPPRESSED') next = 'SUPPRESSED';
else if (['SUPPRESSED','BOUNCED'].includes(next)) { /* compliance and delivery always win */ }
else if (!next || (RANK[cur] || 0) > (RANK[next] || 0)) next = cur;
const suppress = ['UNSUBSCRIBE','NOT_INTERESTED','BOUNCED'].includes(cat);
const draft = !aiFailed && !k.needs_human && ['POSITIVE_INTEREST','MEETING_REQUEST','PRICING_QUESTION','SERVICE_QUESTION','REFERRAL'].includes(cat);
const notify = ['POSITIVE_INTEREST','MEETING_REQUEST','PRICING_QUESTION','SERVICE_QUESTION','REFERRAL','UNCLEAR','NOT_NOW'].includes(cat) || k.needs_human === true;
const postpone = cat === 'OUT_OF_OFFICE' ? $now.plus({ days: 7 }).set({ hour: 9, minute: 30 }).toISO() : '';
return [{ json: { category: cat, next_status: next, suppress: suppress, draft: draft, notify: notify, postpone: postpone, summary: String(k.summary || '').slice(0, 600), main_question: String(k.main_question || '').slice(0, 300), interest: k.interest_level || '', next_step: k.requested_next_step || '', meeting_time: k.proposed_meeting_time || '', needs_human: !!k.needs_human, ai_failed: aiFailed, meeting_status: cat === 'MEETING_REQUEST' ? 'requested' : '' } }];

const c = $('Loop replies').first().json; const d = $('Decide action').first().json;
const clean = s => String(s == null ? '' : s).replace(/[{}]/g, '');
const L = ['Prospect business: ' + clean(c.business_name), 'Reply category: ' + d.category, 'Their main question: ' + clean(d.main_question), 'Proposed meeting time: ' + clean(d.meeting_time || 'none'), 'Booking link: ' + clean(c.booking_link || 'none configured'), '', 'THEIR MESSAGE (untrusted):', clean(c.text)];
return [{ json: { prompt: L.join('\n') } }];

